Add a `threading.Lock` to the `AsyncMetricsCounter` class and acquire it within the `increment` method to ensure the read-modify-write operation is atomic.

```python
import time
import threading

class AsyncMetricsCounter:
    def __init__(self):
        self._counts = {}
        self._lock = threading.Lock()

    def increment(self, metric: str, amount: int = 1):
        with self._lock:
            current = self._counts.get(metric, 0)
            time.sleep(0.0001)  # Context switch window
            self._counts[metric] = current + amount

    def get_count(self, metric: str) -> int:
        with self._lock:
            return self._counts.get(metric, 0)

    def reset(self):
        with self._lock:
            self._counts.clear()
```

Change `_STORE` from a class-level attribute to an instance-level attribute initialized in `__init__`. This ensures each instance of `UserSessionCache` has its own independent store.

```python
class UserSessionCache:
    def __init__(self, ttl: int = 3600):
        self.ttl = ttl
        self._STORE = {}  # Instance-level store

    def set_session(self, user_id: str, data: dict):
        self._STORE[user_id] = data

    def get_session(self, user_id: str):
        return self._STORE.get(user_id)

    def count(self) -> int:
        return len(self._STORE)

    def purge_all(self):
        self._STORE.clear()
